import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 5

def design(feats):
    # Find features with strong association (p < 0.01)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'clinical':
            tstat = feats.x[:, i].T @ feats.y / (np.std(feats.x[:, i]) * np.sqrt(np.sum(feats.y)))
            pval = 2 * (1 - stats.t.cdf(abs(tstat), feats.n - 2))
            if pval < 0.01:
                strong_features.append((fid, pval, feats.x[:, i]))

    # Sort by p-value
    strong_features.sort(key=lambda x: x[1])

    # Check for product terms among top features
    top_features = [f[0] for f in strong_features[:10]]

    # Look for correlated pairs with |r| >= 0.6
    correlations = []
    for i in range(len(top_features)):
        for j in range(i+1, len(top_features)):
            fid1, fid2 = top_features[i], top_features[j]
            col1, col2 = feats.column(fid1), feats.column(fid2)
            corr = np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0,1]
            if abs(corr) >= 0.6:
                correlations.append((fid1, fid2, corr))

    # If we have correlated pairs, consider them as potential drivers
    if correlations:
        # Use the most strongly correlated pair
        best_pair = min(correlations, key=lambda x: -abs(x[2]))
        drivers = (best_pair[0], best_pair[1])

        # Include both features in columns and their product
        columns = (best_pair[0], best_pair[1])
        products = ((best_pair[0], best_pair[1]),)
        loadings = {}

        return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

    # If no strong correlation found, use top individual features
    if strong_features:
        drivers = tuple(f[0] for f in strong_features[:min(MAX_DRIVERS, len(strong_features))])
        columns = drivers
        products = ()
        loadings = {}

        return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

    # No mechanism found
    return Design(drivers=(), columns=(), products=(), loadings={})

